#!/usr/bin/env python3
"""
Concurrent IoT Device Registration Server
Handles multiple device registrations with master timeout.
"""

import socket
import threading
import json
import time
import sys

HOST = '0.0.0.0'
PORT = 5000
MASTER_TIMEOUT = 60

registered_devices = []
lock = threading.Lock()
shutdown_flag = False
server_socket = None

def generate_mac_address(device_id):
    try:
        num_part = device_id.replace('device-', '')
        if len(num_part) >= 4:
            byte1 = num_part[-4:-2].zfill(2)
            byte2 = num_part[-2:].zfill(2)
            return f"DE:AD:BE:EF:{byte1}:{byte2}"
        elif len(num_part) >= 2:
            byte1 = num_part[:2].zfill(2)
            byte2 = num_part[2:].zfill(2)
            return f"DE:AD:BE:EF:{byte1}:{byte2}"
        else:
            return f"DE:AD:BE:EF:00:{num_part.zfill(2)}"
    except Exception as e:
        print(f"Error generating MAC for {device_id}: {e}", file=sys.stderr)
        return None

def handle_client(client_socket, client_addr):
    global registered_devices
    try:
        if shutdown_flag:
            try:
                client_socket.close()
            except:
                pass
            return

        data = client_socket.recv(1024).decode('utf-8').strip()
        if not data:
            return

        device_id = data

        if not device_id.startswith('device-'):
            raise ValueError(f"Invalid device_id format: {device_id} - must start with 'device-'")

        mac_address = generate_mac_address(device_id)
        if mac_address is None:
            raise ValueError(f"Failed to generate MAC address for {device_id}")

        device_info = {"details": {"mac_address": mac_address, "device_id": device_id}}

        with lock:
            registered_devices.append(device_info)

        print(f"[SUCCESS] Registered: {device_id} -> {mac_address}", file=sys.stderr)

        response = json.dumps({"status": "success", "mac_address": mac_address, "device_id": device_id})
        client_socket.sendall(response.encode('utf-8'))

    except Exception as e:
        print(f"[ERROR] Failed to register device: {e}", file=sys.stderr)
        try:
            response = json.dumps({"status": "error", "message": str(e)})
            client_socket.sendall(response.encode('utf-8'))
        except:
            pass
    finally:
        try:
            client_socket.close()
        except:
            pass

def save_results():
    global registered_devices
    try:
        with lock:
            result = list(registered_devices)
        with open('registered_devices.json', 'w') as f:
            json.dump(result, f, indent=2)
        print(f"[INFO] Saved {len(result)} registered devices", file=sys.stderr)
    except Exception as e:
        print(f"[ERROR] Save failed: {e}", file=sys.stderr)

def timeout_worker():
    global shutdown_flag, server_socket
    time.sleep(MASTER_TIMEOUT)
    print(f"[INFO] Timeout ({MASTER_TIMEOUT}s) - shutting down", file=sys.stderr)
    shutdown_flag = True
    if server_socket:
        try:
            server_socket.close()
        except:
            pass

def main():
    global server_socket
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

    try:
        server_socket.bind((HOST, PORT))
        server_socket.listen(5)
        print(f"[INFO] Listening on {HOST}:{PORT}", file=sys.stderr)
        print(f"[INFO] Timeout: {MASTER_TIMEOUT}s", file=sys.stderr)

        t = threading.Thread(target=timeout_worker)
        t.daemon = True
        t.start()

        while True:
            try:
                client, addr = server_socket.accept()
                th = threading.Thread(target=handle_client, args=(client, addr))
                th.daemon = True
                th.start()
            except:
                break
    finally:
        save_results()
        if server_socket:
            try:
                server_socket.close()
            except:
                pass

if __name__ == '__main__':
    main()
SERVEREOF
